# Generated by build.py from recipe.yml for recipe smtp-catch-every-address-in-one-mailbox. Do not edit.
set -e
cd "$(dirname "$0")"
cat > invite.eml <<'EOF'
From: app@example.com
Subject: You are invited

Follow the link to join.
EOF
surl --mail-domain example.com --mailbox app@example.com:apppass --mailbox catchall@example.com:catchpass --mail-catch-all example.com=catchall@example.com smtp://127.0.0.1:8080/ pop3://127.0.0.1:8081/ &
sleep 1
curl --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt user-1@example.com -T invite.eml smtp://127.0.0.1:8080/example.com --next --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt user-2@example.com -T invite.eml smtp://127.0.0.1:8080/example.com --next -u catchall@example.com:catchpass pop3://127.0.0.1:8081/
kill $(jobs -p)
